@namespace sv_e743c72067d2421c9104e68a1429d821.Components.Pages.Settings
@using sv_e743c72067d2421c9104e68a1429d821.Services

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    <div class="row">
        <div class="col-md-6">
            <!-- Theme -->
            <div class="mb-4">
                <label class="form-label fw-bold">Theme</label>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(Theme == theme)"
                               @onchange="() => Theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <label class="form-label fw-bold">Font Size</label>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(FontSize == size)"
                               @onchange="() => FontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <!-- Language -->
            <div class="mb-4">
                <label class="form-label fw-bold">Language</label>
                <select class="form-select" @bind="Language">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="Save">Save</button>
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success mt-3 fade show" role="alert">@_message</div>
            }
        </div>

        <!-- Live Preview -->
        <div class="col-md-6">
            <label class="form-label fw-bold">Preview</label>
            <div class="border rounded @GetPreviewClasses()" style="@GetPreviewStyles()">
                <div class="@(CompactMode ? "p-2" : "p-3")">
                    <h5 class="@(CompactMode ? "mb-1" : "mb-2")">Sample Heading</h5>
                    <p class="@(CompactMode ? "mb-1" : "mb-2")">This is how your content will look with the selected appearance settings.</p>
                    <button class="btn btn-sm @(Theme == "Dark" ? "btn-light" : "btn-primary")">Sample Button</button>
                    <div class="mt-2">
                        <small class="text-muted">Language: @Language | Font: @FontSize | Compact: @(CompactMode ? "On" : "Off")</small>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "Light";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }
    private string? _message;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        return Theme switch
        {
            "Dark" => "bg-dark text-white",
            _ => "bg-light text-dark"
        };
    }

    private string GetPreviewStyles()
    {
        var fontSize = FontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size:{fontSize};min-height:200px;";
    }

    private async Task Save()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        _message = "Appearance saved!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _message = null;
        await InvokeAsync(StateHasChanged);
    }
}

